Definition chk_s (X : expr) : expr := EAlu ALU_SLTU (ELit 0) X.
Definition chk_v (B : expr) (k : Z) : expr := EAlu ALU_ADD (EAlu ALU_AND B (ELit 7)) (ELit k).
(* [comment removed for export] *)
Definition chk_ite (X V O : expr) : expr := EAlu ALU_ADD O (EMd M_MUL (chk_s X) (EAlu ALU_SUB V O)).
(* [comment removed for export] *)
Definition chk_ob (X B : expr) (k : Z) : expr :=
  EAlu ALU_SUB (EMd M_MUL (chk_s X) (EAlu ALU_ADD (chk_v B k) (ELit 1))) (ELit 1).

