Variable segs : list Segment.

(* [comment removed for export] *)
Definition fetch_dec (pc : Z) : option instr :=
  match fetch_word segs (Z_to_bv 64 pc) with
  | None => None
  | Some w =>
      if is_ecall w then None else
      match decode_any w with
      | Some (i, sz) => if Z.eqb sz 4 then Some i else None
      | None => None
      end
  end.

Lemma fetch_dec_ok : forall pc i, fetch_dec pc = Some i ->
  exists w, fetch_word segs (Z_to_bv 64 pc) = Some w /\ is_ecall w = false /\ decode_any w = Some (i, 4%Z).
