(* [comment removed for export] *)
Definition chk_addi (y : reg) (pc : Z) : Z * Z * option (bv 12) :=
  match fetch_dec pc with
  | Some (OpImm ALU_ADD y1 y2 immk) =>
      if (bv_eqb y1 y && bv_eqb y2 y)%bool then (bv_signed immk, pc + 4, Some immk) else (0, pc, None)
  | _ => (0, pc, None)
  end.

(* [comment removed for export] *)
Definition chk_slow (p : Z) (i : instr) : option (reg * reg * reg * bv 13 * bv 12 * option (bv 12) * bv 13 * Z) :=
  match i with
  | Branch BC_NE x r0 imm =>
    if negb (bv_eqb r0 0) then None else
    let slow := bv_unsigned (Z_to_bv 64 (p + bv_signed imm)) in
    match fetch_dec slow with
    | Some (OpImm ALU_AND y b imm7) =>
      if (negb (bv_eqb y 0) && negb (bv_eqb y x) && Z.eqb (bv_signed imm7) 7)%bool then
        let '(k, pb, ao) := chk_addi y (slow + 4) in
        match fetch_dec pb with
        | Some (Branch BC_LT y3 x3 imm3) =>
            if (bv_eqb y3 y && bv_eqb x3 x && Z.eqb (bv_unsigned (Z_to_bv 64 (pb + bv_signed imm3))) (p + 4))%bool
            then Some (x, y, b, imm, imm7, ao, imm3, pb) else None
        | _ => None
        end
      else None
    | _ => None
    end
  | _ => None
  end.

Definition chk_k (ao : option (bv 12)) : Z := match ao with Some immk => bv_signed immk | None => 0 end.

(* [comment removed for export] *)
Definition chk_slow2 (p : Z) (i : instr)
    : option (reg * reg * reg * bv 13 * bv 21 * bv 12 * option (bv 12) * bv 13 * Z * bv 21) :=
  match i with
  | Branch BC_EQ x r0 imm =>
    if negb (bv_eqb r0 0) then None else
    let ok := bv_unsigned (Z_to_bv 64 (p + bv_signed imm)) in
    match fetch_dec (p + 4) with
    | Some (Jal rd1 joff) =>
      if negb (bv_eqb rd1 0) then None else
      let slow := bv_unsigned (Z_to_bv 64 (p + 4 + bv_signed joff)) in
      match fetch_dec slow with
      | Some (OpImm ALU_AND y b imm7) =>
        if (negb (bv_eqb y 0) && negb (bv_eqb y x) && Z.eqb (bv_signed imm7) 7)%bool then
          let '(k, pb, ao) := chk_addi y (slow + 4) in
          match fetch_dec pb with
          | Some (Branch BC_GE y3 x3 imm3) =>
            match fetch_dec (pb + 4) with
            | Some (Jal rd2 joff2) =>
                if (bv_eqb y3 y && bv_eqb x3 x && bv_eqb rd2 0 &&
                    Z.eqb (bv_unsigned (Z_to_bv 64 (pb + 4 + bv_signed joff2))) ok)%bool
                then Some (x, y, b, imm, joff, imm7, ao, imm3, pb, joff2) else None
            | _ => None
            end
          | _ => None
          end
        else None
      | _ => None
      end
    | _ => None
    end
  | _ => None
  end.

Definition chk_try (ss : sym_state) (i : instr) : option (sym_state * sidecond) :=
  match chk_slow (s_pc ss) i with
  | Some (x, y, b, imm, imm7, ao, imm3, pb) =>
      match sym_step segs i ss (SCR [] [] []) with
      | SOk _ _ _ => None
      | SStop =>
          let sr := s_regs ss in
          let X := sr_get sr x in let B := sr_get sr b in let O := sr_get sr y in
          let k := chk_k ao in
          Some (SSR (s_pc ss + 4) (sr_upd sr (ridx y) (chk_ite X (chk_v B k) O)) (s_log ss) (s_know ss) (s_next ss) (s_resv ss),
                SCBr true BC_LT (chk_ob X B k) X)
      end
  | None =>
    match chk_slow2 (s_pc ss) i with
    | None => None
    | Some (x, y, b, imm, joff, imm7, ao, imm3, pb, joff2) =>
        match sym_step segs i ss (SCR [] [] []) with
        | SOk _ _ _ => None
        | SStop =>
            let sr := s_regs ss in
            let X := sr_get sr x in let B := sr_get sr b in let O := sr_get sr y in
            let k := chk_k ao in
            Some (SSR (bv_unsigned (Z_to_bv 64 (s_pc ss + bv_signed imm))) (sr_upd sr (ridx y) (chk_ite X (chk_v B k) O))
                      (s_log ss) (s_know ss) (s_next ss) (s_resv ss),
                  SCBr true BC_LT (chk_ob X B k) X)
        end
    end
  end.

