Fixpoint kxm_go (fuel : nat) (first : bool) (stops : list Z) (scr : scripts) (ss : sym_state)
         (acc : list sidecond) (accs : list (saddr * nat)) : sym_state * list sidecond * scripts * list (saddr * nat) :=
  match fuel with
  | O => (ss, acc, scr, accs)
  | S f =>
    if (negb first && existsb (Z.eqb (s_pc ss)) stops)%bool then (ss, acc, scr, accs) else
    match fetch_word segs (Z_to_bv 64 (s_pc ss)) with
    | None => (ss, acc, scr, accs)
    | Some w =>
      if is_ecall w then (ss, acc, scr, accs) else
      match decode_any w with
      | None => (ss, acc, scr, accs)
      | Some (i, sz) =>
        if negb (Z.eqb sz 4) then (ss, acc, scr, accs) else
        if is_atomic i then (ss, acc, scr, accs) else
        match chk_try ss i with
        | Some (ss2, sc) => kxm_go f false stops scr ss2 (sc_add [sc] acc) accs
        | None =>
          match sym_step segs i ss scr with
          | SStop => (ss, acc, scr, accs)
          | SOk ss2 scs2 scr2 => kxm_go f false stops scr2 ss2 (sc_add scs2 acc) (sacc i ss ++ accs)
          end
        end
      end
    end
  end.

Definition kxm_exec (fuel : nat) (stops : list Z) (scr : scripts) (ss : sym_state) :=
  kxm_go fuel true stops scr ss [] [].

