Section ChkSound.
Context {fx : AS.PropExec.FPState}.
Variable segs : list Segment.

(* [comment removed for export] *)
Lemma chk_slow_spec : forall p i x y b imm imm7 ao imm3 pb,
  chk_slow segs p i = Some (x, y, b, imm, imm7, ao, imm3, pb) ->
  let slow := bv_unsigned (Z_to_bv 64 (p + bv_signed imm)) in
  i = Branch BC_NE x 0%bv imm
  /\ fetch_dec segs slow = Some (OpImm ALU_AND y b imm7) /\ y <> 0%bv /\ y <> x /\ bv_signed imm7 = 7
  /\ match ao with
     | Some immk => fetch_dec segs (slow + 4) = Some (OpImm ALU_ADD y y immk) /\ pb = slow + 8
     | None => pb = slow + 4
     end
  /\ fetch_dec segs pb = Some (Branch BC_LT y x imm3)
  /\ bv_unsigned (Z_to_bv 64 (pb + bv_signed imm3)) = p + 4.
Proof.
