(* [comment removed for export] *)
Lemma chk_slow2_spec : forall p i x y b imm joff imm7 ao imm3 pb joff2,
  chk_slow2 segs p i = Some (x, y, b, imm, joff, imm7, ao, imm3, pb, joff2) ->
  let ok := bv_unsigned (Z_to_bv 64 (p + bv_signed imm)) in
  let slow := bv_unsigned (Z_to_bv 64 (p + 4 + bv_signed joff)) in
  i = Branch BC_EQ x 0%bv imm
  /\ fetch_dec segs (p + 4) = Some (Jal 0%bv joff)
  /\ fetch_dec segs slow = Some (OpImm ALU_AND y b imm7) /\ y <> 0%bv /\ y <> x /\ bv_signed imm7 = 7
  /\ match ao with
     | Some immk => fetch_dec segs (slow + 4) = Some (OpImm ALU_ADD y y immk) /\ pb = slow + 8
     | None => pb = slow + 4
     end
  /\ fetch_dec segs pb = Some (Branch BC_GE y x imm3)
  /\ fetch_dec segs (pb + 4) = Some (Jal 0%bv joff2)
  /\ bv_unsigned (Z_to_bv 64 (pb + 4 + bv_signed joff2)) = ok.
Proof.
