Lemma chk_try_sound : forall RNG E base rom ss ms i ss' sc w,
  fetch_word segs (Z_to_bv 64 (s_pc ss)) = Some w -> is_ecall w = false -> decode_any w = Some (i, 4%Z) ->
  chk_try segs ss i = Some (ss', sc) ->
  sc_denot segs base E sc ->
  st_okR segs E base rom ss ms ->
  exists mr, mstepsF segs RNG ms mr /\ st_okR segs E base rom ss' mr.
Proof.
