Section BridgeM.
Variable segs : list Segment.

Theorem kx_run_evtFM : forall RNG fuel stops scr pc sr kn nx ss' scs scr' accs E R F fc m rom (Q : machine_state -> Prop),
  rfull R ->
  kxm_exec segs fuel stops scr (SS pc sr [] kn nx) = (ss', scs, scr', accs) ->
  regs_ok E sr R -> know_ok segs E m kn -> scs_denot segs m E scs -> Forall (accP RNG E) accs ->
  (log_flat E (s_log ss') ->
   evtF segs RNG Q (MS (kx_regs E (s_regs ss')) F (Z_to_bv 64 (s_pc ss')) fc None (mem_denot E m (s_log ss')) rom)) ->
