Definition learn1 (ts : list ztab) (zs : list zshz) (kn : list kentry) (a : saddr) (n : nat) (sx : bool) (i : nat)
  : list kentry :=
  (if (negb sx && Nat.eqb n 1)%bool then
     match tabs_rule kn ts a with Some (lo, hi) => [KRange (EVar i) lo hi] | None => [] end else [])
  ++ (if (Nat.eqb n 1 && shz_any kn zs a)%bool then [KRange (EVar i) 0 0] else [])
  ++ (if (negb sx && Nat.ltb n 8)%bool then [KRange (EVar i) 0 (2 ^ (8 * Z.of_nat n) - 1)] else []).

Definition learn_step (ts : list ztab) (zs : list zshz) (ss ss2 : sym_state) (scs2 : list sidecond)
  : sym_state * list kentry * list (saddr * nat * bool * nat) :=
  let i := s_next ss in
  if Nat.eqb (s_next ss2) (S i) then
    match rb_find i scs2 with
    | Some (a, n, sx) =>
        let new := learn1 ts zs (s_know ss2) a n sx i in
        (SSR (s_pc ss2) (s_regs ss2) (s_log ss2) (new ++ s_know ss2) (s_next ss2) (s_resv ss2), new, [(a, n, sx, i)])
    | None => (ss2, [], [])
    end
  else (ss2, [], []).

Section LDriver.
Variable segs : list Segment.

Fixpoint kxl_go (ts : list ztab) (zs : list zshz) (fuel : nat) (first : bool) (stops : list Z) (scr : scripts)
         (ss : sym_state) (acc : list sidecond) (accs : list (saddr * nat)) (lk : list kentry)
         (lr : list (saddr * nat * bool * nat))
  : sym_state * list sidecond * scripts * list (saddr * nat) * list kentry * list (saddr * nat * bool * nat) :=
  match fuel with
  | O => (ss, acc, scr, accs, lk, lr)
  | S f =>
    if (negb first && existsb (Z.eqb (s_pc ss)) stops)%bool then (ss, acc, scr, accs, lk, lr) else
    match fetch_word segs (Z_to_bv 64 (s_pc ss)) with
    | None => (ss, acc, scr, accs, lk, lr)
    | Some w =>
      if is_ecall w then (ss, acc, scr, accs, lk, lr) else
      match decode_any w with
      | None => (ss, acc, scr, accs, lk, lr)
      | Some (i, sz) =>
        if negb (Z.eqb sz 4) then (ss, acc, scr, accs, lk, lr) else
        if is_atomic i then (ss, acc, scr, accs, lk, lr) else
        match chk_try segs ss i with
        | Some (ss2, sc) => kxl_go ts zs f false stops scr ss2 (sc_add [sc] acc) accs lk lr
        | None =>
          match sym_step segs i ss scr with
          | SStop => (ss, acc, scr, accs, lk, lr)
          | SOk ss2 scs2 scr2 =>
              let '(ss3, new, nr) := learn_step ts zs ss ss2 scs2 in
              kxl_go ts zs f false stops scr2 ss3 (sc_add scs2 acc) (sacc i ss ++ accs) (new ++ lk) (nr ++ lr)
          end
        end
      end
    end
  end.

Definition kxl_exec (ts : list ztab) (zs : list zshz) (fuel : nat) (stops : list Z) (scr : scripts) (ss : sym_state) :=
  kxl_go ts zs fuel true stops scr ss [] [] [] [].

Definition rv_ok (base : word -> option byte) (E : env) (r : saddr * nat * bool * nat) : Prop :=
  let '(a, n, sx, i) := r in edenot E (EVar i) = rdval segs base (adenot E a) n sx.

Lemma learn1_ok : forall base E kn ts zs a n sx i,
  know_ok segs E base kn -> Forall (tab_ok segs base E) ts -> Forall (shz_ok base E) zs ->
  edenot E (EVar i) = rdval segs base (adenot E a) n sx ->
  know_ok segs E base (learn1 ts zs kn a n sx i).
Proof.
