Lemma learn_step_spec : forall ts zs ss ss2 scs2 ss3 new nr,
  learn_step ts zs ss ss2 scs2 = (ss3, new, nr) ->
  s_pc ss3 = s_pc ss2 /\ s_regs ss3 = s_regs ss2 /\ s_log ss3 = s_log ss2 /\ s_know ss3 = new ++ s_know ss2
  /\ s_next ss3 = s_next ss2 /\ s_resv ss3 = s_resv ss2
  /\ (nr = [] /\ new = [] \/
      exists a n sx, nr = [(a, n, sx, s_next ss)] /\ new = learn1 ts zs (s_know ss2) a n sx (s_next ss)).
