Section LDriverSound.
Context {fx : AS.PropExec.FPState}.
Variable segs : list Segment.

Lemma kxl_go_sound : forall RNG ts zs fuel first stops scr ss acc accs lk lr E base rom,
  s_resv ss = None -> Forall (tab_ok segs base E) ts -> Forall (shz_ok base E) zs ->
  match kxl_go segs ts zs fuel first stops scr ss acc accs lk lr with
  | (r, accr, _, accsr, lkr, lrr) =>
    s_resv r = None /\
