Theorem kx_run_evtFL : forall RNG ts zs fuel stops scr pc sr kn nx ss' scs scr' accs lk lr E R F fc m rom (Q : machine_state -> Prop),
  rfull R ->
  kxl_exec segs ts zs fuel stops scr (SS pc sr [] kn nx) = (ss', scs, scr', accs, lk, lr) ->
  regs_ok E sr R -> know_ok segs E m kn -> Forall (tab_ok segs m E) ts -> Forall (shz_ok m E) zs ->
  Forall (rv_ok segs m E) lr -> scs_denot segs m E scs -> Forall (accP RNG E) accs ->
  (log_flat E (s_log ss') ->
   evtF segs RNG Q (MS (kx_regs E (s_regs ss')) F (Z_to_bv 64 (s_pc ss')) fc None (mem_denot E m (s_log ss')) rom)) ->
